#include "TorrentBridge.h"
#include <libtorrent/session.hpp>
#include <libtorrent/settings_pack.hpp>
#include <libtorrent/torrent_info.hpp>
#include <libtorrent/torrent_status.hpp>
#include <libtorrent/add_torrent_params.hpp>
#include <libtorrent/magnet_uri.hpp>
#include <libtorrent/create_torrent.hpp>
#include <libtorrent/bencode.hpp>
#include <libtorrent/alert_types.hpp>
#include <libtorrent/extensions/ut_metadata.hpp>
#include <libtorrent/extensions/ut_pex.hpp>
#include <sstream>
#include <fstream>
#include <filesystem>
#include <thread>
#include <cstring>
#include <fcntl.h>
#include <unistd.h>
namespace lt=libtorrent;
namespace fs=std::filesystem;
static std::string quoted(std::string const &s){std::ostringstream o;o<<'"';for(unsigned char c:s){if(c=='"'||c=='\\')o<<'\\'<<c;else if(c<32)o<<" ";else o<<c;}o<<'"';return o.str();}
static lt::settings_pack settings(bool network){lt::settings_pack p;p.set_str(lt::settings_pack::user_agent,"ContentTV/0.3");p.set_str(lt::settings_pack::listen_interfaces,network ? "0.0.0.0:0":"127.0.0.1:0");p.set_bool(lt::settings_pack::enable_dht,network);p.set_bool(lt::settings_pack::enable_lsd,false);p.set_bool(lt::settings_pack::enable_upnp,false);p.set_bool(lt::settings_pack::enable_natpmp,false);p.set_int(lt::settings_pack::connections_limit,80);p.set_int(lt::settings_pack::download_rate_limit,0);p.set_int(lt::settings_pack::upload_rate_limit,256*1024);p.set_int(lt::settings_pack::alert_mask,lt::alert_category::error|lt::alert_category::status);return p;}
struct Engine{lt::session session;lt::torrent_handle handle;std::string root;int file=-1;std::shared_ptr<lt::torrent_info const> info;int64_t size=0;bool failed=false;Engine(char const *path,bool network):session(settings(network)),root(path) {}};
static int add(Engine &e,lt::add_torrent_params p){lt::error_code ec;p.save_path=e.root;p.storage_mode=lt::storage_mode_sparse;p.flags&=~lt::torrent_flags::paused;p.flags&=~lt::torrent_flags::auto_managed;p.flags|=lt::torrent_flags::upload_mode;if(p.ti)p.file_priorities.assign(p.ti->num_files(),lt::dont_download);e.handle=e.session.add_torrent(p,ec);return ec ? -1:0;}
extern "C" void *ctv_torrent_create(char const *root,int network){try{if(!root)return nullptr;fs::create_directories(root);return new Engine(root,network!=0);}catch(...){return nullptr;}}
extern "C" void ctv_torrent_destroy(void *p){try{delete static_cast<Engine*>(p);}catch(...) {}}
extern "C" int ctv_torrent_magnet(void *p,char const *uri){try{if(!p||!uri)return -1;lt::error_code ec;auto params=lt::parse_magnet_uri(uri,ec);if(ec)return -1;return add(*static_cast<Engine*>(p),std::move(params));}catch(...){return -1;}}
extern "C" int ctv_torrent_metadata(void *p,uint8_t const *data,size_t length){try{if(!p||!data||length>8*1024*1024)return -1;lt::error_code ec;lt::add_torrent_params params;params.ti=std::make_shared<lt::torrent_info>(lt::span<char const>(reinterpret_cast<char const*>(data),length),ec,lt::from_span);if(ec)return -1;return add(*static_cast<Engine*>(p),std::move(params));}catch(...){return -1;}}
extern "C" char *ctv_torrent_status(void *p){try{if(!p)return nullptr;auto &e=*static_cast<Engine*>(p);if(!e.handle.is_valid())return strdup("{\"files\":[],\"metadata\":false}");auto s=e.handle.status();e.info=e.handle.torrent_file();std::ostringstream out;out<<"{\"metadata\":"<<(e.info ? "true":"false")<<",\"failed\":"<<(s.errc ? "true":"false")<<",\"rate\":"<<s.download_rate<<",\"peers\":"<<s.num_peers<<",\"progress\":"<<s.progress<<",\"files\":[";if(e.info){auto const &f=e.info->files();for(int i=0;i<f.num_files();i++){if(i)out<<',';out<<"{\"index\":"<<i<<",\"name\":"<<quoted(f.file_path(lt::file_index_t{i}))<<",\"size\":"<<f.file_size(lt::file_index_t{i})<<'}';}}out<<"]}";return strdup(out.str().c_str());}catch(...){return nullptr;}}
extern "C" void ctv_torrent_free(char *p){free(p);}
extern "C" int ctv_torrent_select(void *p,int file,int64_t limit){try{if(!p)return -1;auto &e=*static_cast<Engine*>(p);e.info=e.handle.torrent_file();if(!e.info||file<0||file>=e.info->num_files())return -1;auto const &files=e.info->files();auto index=lt::file_index_t{file};auto path=fs::path(files.file_path(index));if(path.is_absolute()||(files.file_flags(index)&lt::file_storage::flag_symlink))return -1;for(auto const &part:path)if(part=="..")return -1;e.size=files.file_size(index);if(e.size<=0||e.size>limit)return -2;e.file=file;std::vector<lt::download_priority_t> priorities(files.num_files(),lt::dont_download);priorities[file]=lt::top_priority;e.handle.prioritize_files(priorities);e.handle.unset_flags(lt::torrent_flags::upload_mode);auto first=files.map_file(index,0,1).piece;auto last=files.map_file(index,e.size-1,1).piece;for(int n=0;n<8&&first+lt::piece_index_t{n}<=last;n++)e.handle.set_piece_deadline(first+lt::piece_index_t{n},n*100);for(int n=0;n<4&&lt::piece_index_t{int(last)-n}>=first;n++)e.handle.set_piece_deadline(lt::piece_index_t{int(last)-n},n*100);return 0;}catch(...){return -1;}}
extern "C" int ctv_torrent_read(void *p,int64_t offset,uint8_t *buffer,int length){try{if(!p||!buffer||length<=0)return -1;auto &e=*static_cast<Engine*>(p);if(e.file<0||!e.info||offset<0||offset>=e.size)return -1;int count=int(std::min<int64_t>(length,e.size-offset));auto const &f=e.info->files();auto request=f.map_file(lt::file_index_t{e.file},offset,count);auto end=f.map_file(lt::file_index_t{e.file},offset+count-1,1).piece;bool ready=true;for(auto piece=request.piece;piece<=end;++piece){if(!e.handle.have_piece(piece)){e.handle.set_piece_deadline(piece,0);ready=false;}}for(int i=1;i<=8&&end+lt::piece_index_t{i}<e.info->end_piece();i++)e.handle.set_piece_deadline(end+lt::piece_index_t{i},i*250);if(!ready)return -2;auto path=fs::path(e.root)/f.file_path(lt::file_index_t{e.file});int fd=open(path.c_str(),O_RDONLY|O_NOFOLLOW);if(fd<0)return -2;int n=int(pread(fd,buffer,count,offset));close(fd);return n>0?n:-2;}catch(...){return -1;}}

// Real peer transfer test over loopback only: no tracker, DHT or remote peer.
extern "C" int ctv_torrent_loopback_test(char const *path){try{fs::path root(path);fs::create_directories(root/"seed");std::string payload(256*1024,' ');for(size_t i=0;i<payload.size();i++)payload[i]=char(i%251);{std::ofstream out(root/"seed"/"sample.mp4",std::ios::binary);out.write(payload.data(),payload.size());}lt::file_storage files;files.add_file("sample.mp4",payload.size());lt::create_torrent maker(files,16*1024,lt::create_torrent::v1_only);lt::error_code ec;lt::set_piece_hashes(maker,(root/"seed").string(),ec);if(ec)return 1;std::vector<char> encoded;lt::bencode(std::back_inserter(encoded),maker.generate());auto ti=std::make_shared<lt::torrent_info>(lt::span<char const>(encoded.data(),encoded.size()),ec,lt::from_span);if(ec)return 2;lt::session seed(settings(false));lt::add_torrent_params params;params.ti=ti;params.save_path=(root/"seed").string();params.flags&=~lt::torrent_flags::paused;params.flags&=~lt::torrent_flags::auto_managed;params.flags|=lt::torrent_flags::seed_mode;auto handle=seed.add_torrent(params,ec);if(ec)return 3;Engine consumer((root/"consumer").c_str(),false);auto magnet=lt::make_magnet_uri(handle);if(ctv_torrent_magnet(&consumer,magnet.c_str())!=0)return 4;for(int i=0;i<100&&seed.listen_port()==0;i++)std::this_thread::sleep_for(std::chrono::milliseconds(50));consumer.handle.connect_peer(lt::tcp::endpoint(lt::make_address("127.0.0.1"),seed.listen_port()));for(int i=0;i<200&&!consumer.handle.torrent_file();i++)std::this_thread::sleep_for(std::chrono::milliseconds(100));if(ctv_torrent_select(&consumer,0,1024*1024)!=0)return 8;std::vector<uint8_t> data(payload.size());for(int i=0;i<200;i++){int n=ctv_torrent_read(&consumer,0,data.data(),int(data.size()));if(n==int(payload.size()))return memcmp(data.data(),payload.data(),payload.size())==0?0:5;std::this_thread::sleep_for(std::chrono::milliseconds(100));}return 6;}catch(...){return 7;}}


